import{_ as i,l as n,o as e,c as r,v as t,p as d,x as o,d as s,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"长视频理解","description":"","frontmatter":{"title":"长视频理解","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/long-video-understanding.md","filePath":"llm/long-video-understanding.md","lastUpdated":1789023840000}'),c={name:"llm/long-video-understanding.md"};function m(_,a,E,A,u,f){const l=n("Mermaid");return e(),r("div",null,[a[1]||(a[1]=t('<h1 id="长视频理解" tabindex="-1">长视频理解 <a class="header-anchor" href="#长视频理解" aria-label="Permalink to &quot;长视频理解&quot;">​</a></h1><div class="epigraph"><p>小时级视频的问题不是「再多几张图」，而是哪些帧进上下文、记忆里留什么、问的是哪一秒。</p><footer>—— 对照 Video-LLaVA / Video-ChatGPT 的短视频对话；MovieChat、LongVA 的长上下文与记忆</footer></div><p><a href="/llm/chart-table-understanding">上一课</a>在单张结构画布上读数。主干<a href="/llm/video-tokens">视频 token</a> 已写抽帧与时间位置。本课缺口是长：超出现场窗口的叙事、重复镜头、要检索的事件。后课多模态推理默认你已经能指向「哪一段」，再谈用看见的当证据。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>短视频 VLM 把 \\(T\\) 帧各编成 \\(N\\) 个 patch，序列是 \\(TN\\)，再加文本。分钟以上会先打爆窗口，相邻帧还高度冗余。均匀低帧率会丢掉闪光与口型；只留关键帧又会丢掉连续动作。问「开头穿什么、结尾有没有同一只包」需要跨段比较，不是当前几秒的 caption。</p><p>MovieChat 把短时记忆与长时记忆分开：近段高分辨率，远处摘要。LongVA 一类把长上下文能力迁到视觉帧序列。没有记忆层次时，所谓长视频只是截断后的短视频。</p><p><span class="marginnote">时间位置必须对齐绝对时间，见视频 token 课。只按「第几张输入帧」编号，2 fps 与 10 fps 下同一物理事件对不上。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三件套：采样策略（均匀 / 动态 FPS / 场景切）；记忆（滑窗、摘要 token、检索过去帧）；提问接口（时间戳、第几分钟）。视觉前端仍是 <a href="/llm/vit-as-encoder">ViT</a> + <a href="/llm/llava-projector">投影器</a>，只是 \\(T\\) 与压缩改变 \\(N_{\\mathrm{total}}\\)。评测要含长时针（事件顺序、跨段指代），不要只用短剪辑 VQA。与生成式视频模型分开：本课是理解，不采样像素。</p>',9)),(e(),d(p,null,{default:o(()=>[h(l,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20VID%5B%22%E9%95%BF%E8%A7%86%E9%A2%91%22%5D%20--%3E%20SMP%5B%22%E6%8A%BD%E5%B8%A7%20%2F%20%E5%9C%BA%E6%99%AF%22%5D%0A%20%20SMP%20--%3E%20MEM%5B%22%E7%9F%AD%E6%97%B6%E4%B8%8E%E9%95%BF%E6%97%B6%E8%AE%B0%E5%BF%86%22%5D%0A%20%20MEM%20--%3E%20LLM%5B%22%E5%B8%A6%E6%97%B6%E9%97%B4%E4%BD%8D%E7%BD%AE%E7%9A%84%20LLM%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>注意力只在当前窗口内混合。长程依赖要么靠把关键帧留在窗口里，要么靠记忆写出的摘要 token——摘要一旦丢掉物体，后面的指代只能靠语言先验，幻觉会回来。因此长视频理解的上限经常是记忆写什么，不是再加一层投影。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>窗口与记忆都有损。下一课在「已经看见」的前提下做多步推理，而不是再加帧。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>长视频是采样 + 记忆 + 时间协议，不是多图拼接。</li><li>摘要会丢物体，跨段指代会退回语言先验。</li><li>评测必须含跨段事件，不只短剪辑 caption。</li><li>出处：Video-LLaVA、Video-ChatGPT；MovieChat；LongVA。</li></ul>',6))])}const V=i(c,[["render",m]]);export{T as __pageData,V as default};
